ssize_t archive_write_data(struct archive* _a, const void* buff, size_t s) {
    ssize_t result;

    if (_a == NULL || buff == NULL || s == 0) {
        archive_set_error(_a, ARCHIVE_ERRNO_MISC, "Invalid argument");
        return -1;
    }

    if (_a->archive_magic != ARCHIVE_MAGIC) {
        archive_set_error(_a, ARCHIVE_ERRNO_MISC, "Archive object is invalid or not properly initialized");
        return -1;
    }

    if (s > SSIZE_MAX) {
        s = SSIZE_MAX;
    }

    archive_clear_error(&_a->error);

    result = _a->write_data(_a, buff, s);

    if (result < 0) {
        archive_copy_error(&_a->error, &_a->error);
    }

    return result;
}

ssize_t archive_write_data(struct archive* _a, const void* buff, size_t s) {
    if (_a == NULL || buff == NULL || s == 0)
        return -1;

    if (_a->magic != ARCHIVE_MAGIC)
        return -1;

    size_t bytes_to_write = s;
    if (bytes_to_write > (size_t)ARCHIVE_WRITE_MAX)
        bytes_to_write = (size_t)ARCHIVE_WRITE_MAX;

    _a->bytes_written = 0;
    _a->error = ARCHIVE_OK;

    ssize_t result = _a->format_write_data(_a, buff, bytes_to_write);
    if (result < 0) {
        _a->error = result;
        return -1;
    }

    _a->bytes_written += result;
    return result;
}
